import Foundation

/// An item in stock.
struct Item: Equatable {
    let name: String
    var count: Int = 0
}

enum Level {
    case low, high
}

protocol Store {
    func add(_ item: Item) throws
    var total: Int { get }
}

enum StoreError: Error {
    case full(limit: Int)
}

final class MemoryStore: Store {
    private var items: [String: Item] = [:]
    let limit: Int

    init(limit: Int) {
        self.limit = limit
    }

    func add(_ item: Item) throws {
        guard items.count < limit else {
            throw StoreError.full(limit: limit)
        }
        items[item.name] = item
    }

    var total: Int {
        items.values.reduce(0) { $0 + $1.count }
    }
}

func level(of item: Item?) -> Level {
    switch item?.count ?? 0 {
    case 0..<100:
        return .low
    default:
        return .high
    }
}

let store = MemoryStore(limit: 4)
for i in 1...3 {
    try? store.add(Item(name: "item\(i)", count: i * 10))
}
// Print a summary.
print("total: \(store.total), level: \(level(of: nil))")

